function mosAlgorithm(arr, queries) {
  const n = arr.length;
  const q = queries.length;
  const blockSize = Math.max(1, Math.floor(Math.sqrt(n)));

  // attach original index to each query for answer reconstruction
  const indexedQueries = queries.map(([l, r], i) => [l, r, i]);

  // sort: by left block, then right endpoint (zigzag for even/odd blocks)
  indexedQueries.sort(([l1, r1], [l2, r2]) => {
    const b1 = Math.floor(l1 / blockSize);
    const b2 = Math.floor(l2 / blockSize);
    if (b1 !== b2) return b1 - b2;
    // zigzag: even blocks sort r ascending, odd blocks sort r descending
    return b1 % 2 === 0 ? r1 - r2 : r2 - r1;
  });

  // --- problem-specific state ---
  const freq = new Array(n).fill(0);
  let distinct = 0; // current answer: count of distinct elements

  function add(i) {
    if (freq[arr[i]] === 0) distinct++;
    freq[arr[i]]++;
  }

  function remove(i) {
    freq[arr[i]]--;
    if (freq[arr[i]] === 0) distinct--;
  }
  // --- end problem-specific state ---

  const answers = new Array(q);
  let curL = 0, curR = -1;

  for (const [l, r, idx] of indexedQueries) {
    // expand/shrink window to [l, r]
    while (curR < r) add(++curR);
    while (curL > l) add(--curL);
    while (curR > r) remove(curR--);
    while (curL < l) remove(curL++);

    // store answer at original query index
    answers[idx] = distinct;
  }

  return answers;
}
